/* A single analyser on MAHA's existing persistent audio element. */
(()=>{'use strict';
const frame=document.getElementById('music-frame'),dock=document.getElementById('listen-player'),title=document.getElementById('dock-expand'),panel=document.getElementById('dock-panel');
const mini=document.createElement('span');mini.className='music-mini-spectrum';mini.setAttribute('aria-hidden','true');
for(let i=0;i<5;i++)mini.append(document.createElement('i'));
title.prepend(mini);
const strip=document.createElement('div');strip.className='music-spectrum';strip.setAttribute('aria-hidden','true');const caption=document.createElement('div');caption.className='spectrum-caption';caption.textContent='AUDIO SPECTRUM';const canvas=document.createElement('canvas');const scaleLabels=document.createElement('div');scaleLabels.className='spectrum-scale';for(const text of ['60 Hz','250','1k','4k','16k']){const label=document.createElement('span');label.textContent=text;scaleLabels.append(label);}strip.append(caption);strip.append(canvas);strip.append(scaleLabels);panel.querySelector('.listen-artwork').after(strip);
const motion=matchMedia('(prefers-reduced-motion: reduce)');let context,source,analyser,audio,bins,raf=0,last=0,failed=false;const levels=new Float32Array(32);const pen=canvas.getContext('2d');
function reset(){levels.fill(0);mini.dataset.active='false';mini.querySelectorAll('i').forEach(b=>b.style.height='3px');if(pen)pen.clearRect(0,0,canvas.width,canvas.height);}
function stop(){cancelAnimationFrame(raf);raf=0;reset();}
function eligible(){return audio&&!audio.paused&&!audio.ended&&!document.hidden&&!motion.matches&&!failed&&analyser&&context.state==='running';}
function tick(now){raf=0;if(!eligible()){reset();return;}raf=requestAnimationFrame(tick);if(now-last<33)return;last=now;analyser.getByteFrequencyData(bins);const color=getComputedStyle(dock).getPropertyValue('--accent').trim()||'#c9ef70';mini.dataset.active='true';
for(let i=0;i<32;i++){const start=Math.floor(2*Math.pow(300,i/32)),end=Math.min(bins.length,Math.ceil(2*Math.pow(300,(i+1)/32)));let sum=0;for(let j=start;j<end;j++)sum+=bins[j];const value=end>start?sum/(end-start)/255:0;levels[i]=Math.max(value,levels[i]*.82);}
for(let i=0;i<5;i++){let peak=0;for(let j=i*6;j<(i+1)*6;j++)peak=Math.max(peak,levels[j]);mini.children[i].style.height=(3+peak*13)+'px';}
if(!panel.hidden&&pen){const width=canvas.clientWidth,height=64,scale=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(width*scale)||canvas.height!==height*scale){canvas.width=Math.round(width*scale);canvas.height=height*scale;}pen.setTransform(scale,0,0,scale,0,0);pen.clearRect(0,0,width,height);const gradient=pen.createLinearGradient(0,height,0,0);gradient.addColorStop(0,color);gradient.addColorStop(.65,'#b4ddd0');gradient.addColorStop(1,'#f4e8ab');pen.fillStyle=gradient;const step=width/32;for(let i=0;i<32;i++){const count=Math.round(levels[i]*12);for(let j=0;j<12;j++){pen.globalAlpha=j<count?.9:.055;pen.fillRect(i*step,height-4-j*5,Math.max(1,step-3),3);}if(count>0){pen.globalAlpha=.8;pen.fillRect(i*step,height-4-count*5,Math.max(1,step-3),1);}}pen.globalAlpha=1;}}

function start(){if(eligible()&&!raf)raf=requestAnimationFrame(tick);else if(!eligible())stop();}
function unlock(){if(motion.matches||failed||!audio)return;try{if(!context){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;context=new AC();source=context.createMediaElementSource(audio);analyser=context.createAnalyser();analyser.fftSize=2048;analyser.smoothingTimeConstant=.72;bins=new Uint8Array(analyser.frequencyBinCount);source.connect(analyser);analyser.connect(context.destination);}if(context.state==='suspended')context.resume().then(start).catch(()=>{});else start();}catch(error){/* Preserve sound if analysis cannot be connected. */if(source&&context)try{source.disconnect();source.connect(context.destination);}catch{}failed=true;stop();}}
function bind(){try{const doc=frame.contentDocument,next=doc?.getElementById('audio');if(!next||next===audio)return;audio=next;doc.addEventListener('pointerdown',unlock,true);doc.addEventListener('keydown',unlock,true);audio.addEventListener('play',()=>{unlock();start();});audio.addEventListener('playing',start);for(const event of ['pause','ended','emptied'])audio.addEventListener(event,stop);}catch{}}
frame.addEventListener('load',bind);bind();document.addEventListener('pointerdown',unlock,true);document.addEventListener('keydown',unlock,true);document.addEventListener('visibilitychange',start);motion.addEventListener('change',()=>{if(motion.matches)stop();else{unlock();start();}});reset();
})();

